Definition impl_one (w i vb this vcap : Z) : implv := mkIMPL (mkSPC VP_SPCI_IMPL 1 w i) 0 vb [this] vcap.
Definition impl_none (w i vb vcap : Z) : implv := mkIMPL (mkSPC VP_SPCI_IMPL 1 w i) 0 vb [] vcap.

Definition state_remove_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (implb vb w i vcap lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (rm_W lo sp implb vb) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ ImplBlock LB m' implb (impl_none w i vb vcap).

Definition state_remove_stmt : Prop :=
  forall (stb implb vb w i vcap lo : Z) (LB : list block)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  ro_cells rsegs m (stb + 88) [C8 (wz (implb + 32)); C8 (wz implb)] -> stb mod 16 = 0 -> stb + SZ_SPCI_STATE <= hceil ->
  (* [comment removed for export] *)
  ImplBlock LB m implb (impl_one w i vb (stb + 32) vcap) ->
  (stb + SZ_SPCI_STATE <= implb \/ implb + SZ_SPCI_IMPL <= stb) ->
  (stb + SZ_SPCI_STATE <= vb \/ vb + 8 * vcap <= stb) ->
  (vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + STATE_REMOVE_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp mod 16 = 0 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (state_remove_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB implb vb w i vcap lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (stb + 32)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STATE_REMOVE) fc None m (seg_rom rsegs)).


(* The vector of one state, as the walk reads it (one C8) and as impl_none states it (empty, the
   stale element folded into the spare capacity). *)
Lemma rm_vec_one : forall m vb x n junk,
  rw_cells rsegs m vb [CB (8 * length [x]) (flat_map le8z [x]); CB n junk] ->
  rw_cells rsegs m vb [C8 (wz x); CB n junk].
Proof.
  intros m vb x n junk H. eapply rw_cells_reshape; [exact H| |].
  - destruct H as [[WF _] _]. cbn [cells_wf cell_wf] in WF |- *. destruct WF as (_ & WJ & _).
    split; [exact I| split; [exact WJ| exact I]].
  - cbn [cells_bytes cbytes flat_map]. unfold le8z. rewrite !app_nil_r. reflexivity.
Qed.

Lemma rm_vec_none : forall m vb x n junk vcap,
  rw_cells rsegs m vb [C8 (wz x); CB n junk] -> (8 + n)%nat = Z.to_nat (8 * vcap) ->
  rw_cells rsegs m vb [CB (8 * length (@nil Z)) (flat_map le8z []);
                       CB (Z.to_nat (8 * (vcap - zlength (@nil Z)))) (le8z x ++ junk)].
Proof.
  intros m vb x n junk vcap H E. eapply rw_cells_reshape; [exact H| |].
  - destruct H as [[WF _] _]. cbn [cells_wf cell_wf] in WF |- *. destruct WF as (_ & WJ & _).
    split; [reflexivity| split; [|exact I]].
    unfold zlength. cbn [length Z.of_nat]. rewrite Z.sub_0_r, length_app, WJ. unfold le8z. rewrite length_le8. exact E.
  - cbn [cells_bytes cbytes flat_map app]. unfold le8z. rewrite !app_nil_r. reflexivity.
Qed.

Lemma rm_cap_nat : forall vcap, 1 <= vcap -> (8 + Z.to_nat (8 * (vcap - 1)))%nat = Z.to_nat (8 * vcap).
Proof.
  intros vcap H. replace (8 + Z.to_nat (8 * (vcap - 1)))%nat with (Z.to_nat (8 + 8 * (vcap - 1))).
  - f_equal. ring.
  - rewrite Z2Nat.inj_add by (Lia.lia). reflexivity.
Qed.

Lemma rm_amo : forall implb, 0 <= implb -> implb + 8 < 2^64 -> implb mod 16 = 0 ->
  amo_aligned AW (Z_to_bv 64 (implb + 8)) = true.
Proof.
  intros implb H0 H1 H16. apply amo_aligned_intro; [split; lia|].
  destruct (proj1 (Z.mod_divide implb 16 ltac:(discriminate)) H16) as [k Hk]. rewrite Hk.
  replace (k * 16 + 8) with ((k * 4 + 2) * 4) by ring. apply Z.mod_mul. discriminate.
Qed.

(* The three vector words, compared word by word, so that `f_equal` never splits a `Z.add`. *)
Lemma rm_c8x3_bytes : forall a b c a' b' c' : word, a = a' -> b = b' -> c = c' ->
  cells_bytes [C8 a; C8 b; C8 c] = cells_bytes [C8 a'; C8 b'; C8 c'].
Proof. intros a b c a' b' c' -> -> ->. reflexivity. Qed.
Local Ltac rm_word_eq := first [ reflexivity | apply Z_to_bv_eqm; rewrite ?unsigned_lit by lia; Z.div_mod_to_equations; lia ].

(* Branch closers. Every branch of this walk is data-dependent, so solve_cond cannot decide it: take
   both arms and refute the impossible one explicitly (never `try first [if_false | if_true]`). *)
Local Ltac rm_kill K :=
  exfalso;
  first [ revert K; rewrite ?unsigned_lit by lia; lia
        | vm_compute in K; discriminate
        | vm_compute in K; exact (K eq_refl)
        | vm_compute in K; lia ].
Local Ltac br_nt := let K := fresh "K" in if_cases K; zify_cond K; [ rm_kill K | clear K ].
Local Ltac br_tk := let K := fresh "K" in if_cases K; zify_cond K; [ clear K | rm_kill K ].
Local Ltac ra_even := first [ rewrite unsigned_lit by lia; reflexivity | vm_compute; reflexivity ].
Lemma state_remove_spec : state_remove_stmt.
Proof.
  unfold state_remove_stmt, STATE_REMOVE_STACK, P_STATE_REMOVE.
  intros stb implb vb w i vcap lo LB ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    F fc m RO S16 SHI IB SEP1 SEP2 SEP3 ST LO CE SP16 RA MI.
  unfold impl_one in IB.
  destruct (ImplBlock_open _ _ _ _ IB) as (p & j7 & IN & RB & CH & OK & EV & PM & VC & LE & VS). clear IB.
  cbn [im_hdr im_lk im_vb im_states im_vcap] in *.
  change (zlength [stb + 32]) with 1 in *.
  destruct VS as [[V0 _] | (q & junk & INQ & RBV & VC0 & VCELLS)]; [exfalso; lia|].
  apply rm_vec_one in VCELLS.
  unfold SpcHdrCells in CH. cbn [spc_vptr spc_use spc_weak spc_init] in CH.
  destruct PM as (PMC & _ & PAL). unfold PMutexCells, zeros in PMC. cbn [repeat] in PMC.
  unfold SZ_SPCI_IMPL, SZ_SPCI_STATE, MTX_UNLOCK_STACK, rm_W, wz in *.
  pose proof hceil_range as HCR.
  pose proof (bv_unsigned_in_range 64 sp) as SPB. unfold bv_modulus in SPB. change (2 ^ Z.of_N 64) with (2^64) in SPB.
  pose proof RB as (RB0 & RB16 & _ & RBH & _).
  pose proof RBV as (RV0 & _ & _ & RVH & _).
  pose proof (rm_amo implb ltac:(lia) ltac:(lia) RB16) as AMO.
  pose proof (munch_refl [(lo, bv_unsigned sp); (implb + 8, implb + 12); (implb + 32, implb + 72);
                          (implb + 80, implb + 88); (vb, vb + 8)]%Z m) as MU.
  pose proof (wmono_refl rsegs m) as WM.
  carve_frame 48%nat ST.
  (* addi sp, sp, -48; sd ra, 40(sp); sd s0, 32(sp); sd s1, 24(sp); sd s2, 16(sp) *)
  step. step. step. step. step.
  (* ld a1, 64(a0): implb, read at stb + 96 *)
  step.
  (* sd zero, 0(sp); sd a1, 8(sp) *)
  st1. step.
  (* beqz a1: not taken *)
  step. br_nt.
  (* mv s0, a0; lw a0, 8(a1): the use count, 1 *)
  step. step. rewrite ?sx32_lit by lia.
  (* beqz a0: not taken *)
  step. br_nt.
  (* addi a1, a1, 8; addiw a2, a0, 1; sext.w a3, a0 *)
  step. st1. st1. rewrite ?sx32_lit by lia.
  (* lr.w a0, (a1): the count, 1 *)
  amo_step AMO. rewrite ?sx32_lit by lia.
  (* bne a0, a3: not taken, the lr read the same count *)
  step. br_nt.
  (* sc.w a4, a2, (a1): the reservation is the lr's (one hart), so the count becomes 2 and a4 is 0 *)
  amo_step AMO.
  (* bnez a4: not taken *)
  step. br_nt.
  (* beq a0, a3: TAKEN, out of the retry loop to 0x38b28 *)
  step. br_tk.
  (* ld a0, 56(s0): implb + 32, read at stb + 88; sd a0, 0(sp) *)
  step. step.
  (* beqz a0: not taken *)
  step. br_nt.
  (* mv a0, sp; jal P_SP_IMPL_ARROW *)
  step. step.
  pose proof (sp_arrow_spec_at P_SP_IMPL_ARROW (or_intror eq_refl)) as SPA.
  unfold sp_arrow_stmt, P_SP_IMPL_ARROW, SP_ARROW_STACK in SPA.
  (* Fix the pointee and stack floor before callZ transports the caller's munch hypothesis.
     callZ also normalizes the callee's stack bound for release_frame. *)
  callZ (SPA (bv_unsigned sp + -48) (implb + 32) lo);
    [ lazymatch goal with FRc : rw_cells _ _ (bv_unsigned sp + -48) _ |- _ =>
        pose proof (rw_cells_ro_cell _ _ _ _ 0%nat _ FRc eq_refl) as RO0; cbn [Z.of_nat] in RO0;
        rewrite Z.add_0_r in RO0; exact RO0 end
    | lia
    | lia
    | rewrite ?unsigned_lit by lia; eassumption
    | rewrite ?unsigned_lit by lia; lia
    | lia
    | left; rewrite ?unsigned_lit by lia; lia
    | ra_even
    | assumption
    | ].
  clear SPA. unfold wz in *.
  (* mv s1, a0; jal P_MTX_LOCK *)
  step. step.
  pose proof mtx_lock_spec as MLK. unfold mtx_lock_stmt, mtx_lock_post, P_MTX_LOCK, MTX_LOCK_STACK, wz in MLK.
  callZ (MLK (implb + 32) lo);
    [ split; [unfold PMutexCells, zeros; cbn [repeat]; eassumption | split; [left; reflexivity | exact PAL]]
    | rewrite ?unsigned_lit by lia; eassumption
    | unfold MTX_LOCK_STACK; rewrite ?unsigned_lit by lia; lia
    | lia
    | left; lia
    | ra_even
    | assumption
    | ].
  unfold wz in *.
  lazymatch goal with HP : PMutex _ _ EBUSY |- _ =>
    destruct HP as (PMC2 & _ & _); unfold PMutexCells, zeros in PMC2; cbn [repeat] in PMC2 end.
  (* ld a3, 48(s1): vb + 8; ld a2, 40(s1): vb; ld a1, -8(a3): stb + 32; addi a0, a3, -8 *)
  step. step. step. step.
  (* beq a2, a3: not taken, the vector is not empty *)
  step. br_nt.
  (* ld a4, 0(a2): stb + 32 *)
  step.
  (* beq a4, s0: TAKEN, the state is the first element *)
  step. br_tk.
  (* sd a1, 0(a2) (the last element over the found one: the same value); sd a0, 48(s1) (end := vb) *)
  step. step.
  (* mv a0, s1; jal P_MTX_UNLOCK *)
  step. step.
  pose proof mtx_unlock_spec as MUL. unfold mtx_unlock_stmt, mtx_unlock_post, P_MTX_UNLOCK, MTX_UNLOCK_STACK, wz in MUL.
  callZ (MUL (implb + 32) lo);
    [ split; [unfold PMutexCells, zeros; cbn [repeat]; eassumption | split; [right; reflexivity | exact PAL]]
    | rewrite ?unsigned_lit by lia; eassumption
    | unfold MTX_UNLOCK_STACK; rewrite ?unsigned_lit by lia; lia
    | lia
    | left; lia
    | ra_even
    | assumption
    | ].
  clear MLK MUL. unfold wz in *.
  (* the mutex cells after unlock, for ImplBlock_close at the end (a PMutex hypothesis is not transported by stores) *)
  lazymatch goal with HP : PMutex _ _ 0 |- _ =>
    destruct HP as (PMC3 & _ & _); unfold PMutexCells, zeros in PMC3; cbn [repeat] in PMC3 end.
  (* ld s0, 8(sp): implb; beqz s0: not taken *)
  step. step. br_nt.
  (* addi a0, s0, 8; li s1, -1; amoadd.w.aqrl a0, s1, (a0): the count 2 -> 1, old value 2 *)
  step. step. amoadd_step AMO.
  (* li s2, 1; bne a0, s2: TAKEN (2 <> 1), to the epilogue: the deleter calls are never reached *)
  step. step. br_tk.
  (* ld ra, 40(sp); ld s0, 32(sp); ld s1, 24(sp); ld s2, 16(sp) *)
  step. step. step. step.
  lazymatch goal with FRc : rw_cells _ _ (bv_unsigned sp + -48) _, STc : stk _ _ lo _ |- _ =>
    release_frame FRc STc (bv_unsigned sp) end.
  (* addi sp, sp, 48; ret *)
  step. step.
  finish.
  all: lazymatch goal with
       | |- ImplBlock _ _ _ _ =>
           unfold impl_none; eapply ImplBlock_close; cbn [im_hdr im_lk im_vb im_states im_vcap];
           [ exact IN
           | exact RB
           | unfold SpcHdrCells; cbn [spc_vptr spc_use spc_weak spc_init]; eassumption
           | exact OK
           | first [exact EV | reflexivity]
           | split; [unfold PMutexCells, zeros; cbn [repeat]; eassumption | split; [left; reflexivity | exact PAL]]
           | eapply rw_cells_reshape; [eassumption | cbn; repeat split |];
             unfold wz, zlength; cbn [length Z.of_nat]; apply rm_c8x3_bytes; rm_word_eq
           | unfold zlength; cbn [length Z.of_nat]; lia
           | right; exists q, (le8z (stb + 32) ++ junk);
             split; [exact INQ| split; [exact RBV| split; [lia| eapply rm_vec_none; [eassumption| apply rm_cap_nat; lia]]]] ]
       end.
Qed.
End HCW.
